6	use clap::Parser;
7	use log::{debug, info};
8	
9	#[derive(Parser)]
10	#[command(
11	    version,
12	    about = concat!(
13	        "iiac-perf ",
14	        env!("CARGO_PKG_VERSION"),
15	        " — Rust latency microbenchmark harness",
16	    ),
17	    max_term_width = 80,
18	)]
19	struct Cli {
20	    /// Benches to run. Pass 'all' for every registered bench, or
21	    /// one or more names. Run with no args to see the available list.
22	    benches: Vec<String>,
23	
24	    /// Target wall-clock seconds per bench (default 5.0). Auto-sizes
25	    /// outer and inner loop counts. Mutually exclusive with -D.
26	    #[arg(short = 'd', long, conflicts_with = "total_duration")]
27	    duration: Option<f64>,
28	
29	    /// Target total wall-clock seconds across all requested benches;
30	    /// budget is split equally per bench. Mutually exclusive with -d.
31	    #[arg(short = 'D', long)]
32	    total_duration: Option<f64>,
33	
34	    /// Override outer loop count (skips auto-sizing; inner still adapts).
35	    #[arg(short, long)]
36	    outer: Option<u64>,
37	
38	    /// Override inner loop count (skips auto-sizing).
39	    /// inner=1 measures single-call latency (each sample = one step); higher
40	    /// inner measures back-to-back/burst rate (each sample = N steps averaged).
41	    #[arg(short, long)]
42	    inner: Option<u64>,
43	
44	    /// Pin bench threads to logical CPUs (comma-separated, ranges OK).
45	    /// The list is a core *pool*: thread `i` of a bench is pinned to
46	    /// `pool[i % pool.len()]`, so shorter pools oversubscribe by wrap.
47	    /// Examples: `--pin 0,1` (2 threads → 2 CPUs), `--pin 0-5` (6-thread
48	    /// pool), `--pin 0,0` (two threads on the same CPU). On 3900X,
49	    /// logical CPUs N and N+12 are SMT siblings of the same physical
50	    /// core — `--pin 0,12` pairs siblings (max contention), `--pin 0,1`
51	    /// gives independent cores. Omit to leave threads unpinned.
52	    #[arg(long, value_name = "CORES")]
53	    pin: Option<String>,
54	
55	    /// Skip pinning the main thread for calibration. Always takes
56	    /// effect, including when `--pin` is set — bench threads still
57	    /// pin per `--pin`, but main stays on whatever affinity mask
58	    /// the process launched with. By default (without this flag),
59	    /// calibration runs with main pinned to `pin[0]` if set, else
60	    /// core 0, so framing/loop come from a stable environment.
61	    /// Pass this flag to decouple the calibration environment from
62	    /// the bench pinning pool (or to reproduce pre-0.6.0 behavior
63	    /// when `--pin` is absent).
64	    #[arg(long)]
65	    no_pin_cal: bool,
66	
67	    /// Enable verbose internals on stderr: affinity mask, cal
68	    /// parameters and raw fit inputs, calibration wall time.
69	    /// Equivalent to `RUST_LOG=debug`. Default is `warn` (silent
70	    /// unless something's wrong). `RUST_LOG` overrides this flag
71	    /// when set, so per-module filtering still works.
72	    #[arg(short, long)]
73	    verbose: bool,
74	}
75	
76	const DEFAULT_DURATION: f64 = 5.0;
77	
78	fn main() {
79	    let cli = Cli::parse();
80	
81	    // Default filter is `warn`; `-v` bumps to `debug`. `RUST_LOG`
82	    // (if set) always wins — so users can still do fine-grained
83	    // per-module filtering without fighting the flag.
84	    let mut builder = env_logger::Builder::from_default_env();
85	    if std::env::var_os("RUST_LOG").is_none() {
86	        builder.filter_level(if cli.verbose {
87	            log::LevelFilter::Debug
88	        } else {
89	            log::LevelFilter::Warn
90	        });
91	    }
92	    builder.format_timestamp(None).init();
93	
94	    if cli.benches.is_empty() {
95	        println!("no benches specified. use -h or --help for more info.");
96	        println!("available: all, {}", benches::names().join(", "));
97	        return;
98	    }
99	
100	    println!(
101	        "iiac-perf {} — Rust latency microbenchmark harness\n",
102	        env!("CARGO_PKG_VERSION")
103	    );
104	
105	    if let Some(mask) = pin::current_affinity() {
106	        info!("startup affinity: {}", pin::affinity_summary(&mask));
107	    }
108	
109	    let pin_cores: Vec<usize> = match cli.pin.as_deref() {
110	        None => Vec::new(),
111	        Some(spec) => match pin::parse_cores(spec) {
112	            Ok(v) => v,
113	            Err(e) => {
114	                eprintln!("error: --pin: {e}");
115	                std::process::exit(2);
116	            }
117	        },
118	    };
119	
120	    // Pin main for calibration. Always pinned by default so
121	    // framing/loop numbers come from a stable environment
122	    // regardless of --pin. --no-pin-cal restores pre-0.6.0
123	    // behavior (pin iff --pin given).
124	    //
125	    // When we're doing the cal-only pin (--pin absent, --no-pin-cal
126	    // absent), snapshot the pre-cal affinity and restore it after
127	    // calibrate() so the scheduler regains freedom to co-locate
128	    // bench threads — otherwise main's pin leaks into the
129	    // scheduler's placement decisions and suppresses the
130	    // "both ends hot and spinning" fast path.
131	    let cal_pin: Option<usize> = if cli.no_pin_cal {
132	        None
133	    } else {
134	        pin_cores.first().copied().or(Some(0))
135	    };
136	    // Save/restore pre-cal affinity whenever we're about to set a
137	    // cal pin that wasn't the user's explicit bench-pin request —
138	    // i.e. the cal-only pin (--pin absent, --no-pin-cal absent).
139	    // --pin ⇒ user already wants main on pin[0]; leave alone.
140	    // --no-pin-cal ⇒ we aren't pinning at all; nothing to save.
141	    let saved_affinity = if pin_cores.is_empty() && !cli.no_pin_cal {
142	        pin::save_affinity()
143	    } else {
144	        None
145	    };
146	    pin::pin_current(cal_pin);
147	
148	    if let Some(cpu) = cal_pin {
149	        info!("pinned main to core {cpu} for calibration");
150	    } else {
151	        info!("cal pin skipped");
152	    }
153	    if let Some(mask) = pin::current_affinity() {
